import { useState } from 'react';
import { Chip } from '../components/Chip.jsx';
import { Field } from '../components/Field.jsx';
import './notes-toolbar.css';

const FILTERS = ['All', 'Mine', 'Shared'];

export function NotesToolbar({ onChange }) {
  const [filter, setFilter] = useState('All');
  const [query, setQuery] = useState('');
  const [pinned, setPinned] = useState(false);

  const update = (next) => onChange?.({ filter, query, pinned, ...next });

  return (
    <div className="notes-toolbar" role="toolbar" aria-label="Notes">
      <div className="notes-toolbar__filters" role="group" aria-label="Filter notes">
        {FILTERS.map((name) => (
          <Chip
            key={name}
            Label={name}
            Size="L"
            pressed={filter === name}
            onClick={() => { setFilter(name); update({ filter: name }); }}
          />
        ))}
      </div>
      <Field
        label="Search notes"
        type="search"
        placeholder="Search notes"
        value={query}
        onChange={(e) => { setQuery(e.target.value); update({ query: e.target.value }); }}
      />
      {/* Tidepool's chip has no icon-only variant: Label is left empty and the name comes from aria-label. */}
      <Chip
        className="chip chip--l notes-toolbar__pin"
        Label=""
        Size="L"
        Icon
        pressed={pinned}
        aria-label="Pin note"
        title="Pin note"
        onClick={() => { setPinned(!pinned); update({ pinned: !pinned }); }}
      />
    </div>
  );
}

