import { useState } from 'react';
import { Chip } from '../components/Chip';
import { Field } from '../components/Field';
import './notes-toolbar.css';
// Prototype. Two stand-ins for gaps in Tidepool (see notes-toolbar.css): a selected look for chips, and an icon-only chip.
const FILTERS = ['All', 'Mine', 'Shared'];
export function NotesToolbar({ onFilterChange, onSearch, onPinChange }) {
  const [filter, setFilter] = useState('All');
  const [pinned, setPinned] = useState(false);
  const selectFilter = (next) => { setFilter(next); onFilterChange?.(next); };
  const togglePin = () => { setPinned(!pinned); onPinChange?.(!pinned); };
  return (
    <div className="notes-toolbar" role="toolbar" aria-label="Notes">
      <div className="notes-toolbar__filters" role="group" aria-label="Filter notes">
        {FILTERS.map((name) => (
          <Chip key={name} Label={name} pressed={filter === name} onClick={() => selectFilter(name)} />
        ))}
      </div>
      <div className="notes-toolbar__search">
        <Field label="Search notes" type="search" placeholder="Search notes" onChange={(e) => onSearch?.(e.target.value)} />
      </div>
      <span className="notes-toolbar__pin">
        <Chip Label="" Size="L" Icon aria-label="Pin note" title={pinned ? 'Unpin note' : 'Pin note'} pressed={pinned} onClick={togglePin} />
      </span>
    </div>
  );
}

