import { Chip } from '../components/Chip.jsx';
import { Field } from '../components/Field.jsx';
import './notes-toolbar.css';

const FILTERS = ['All', 'Mine', 'Shared'];

// Prototype: composes Tidepool components; the two gaps (selected chip, icon-only chip) are patched in notes-toolbar.css.
export function NotesToolbar({ onFilterChange, onSearch, onPinChange }) {
  const [filter, setFilter] = useState('All');
  const [pinned, setPinned] = useState(false);

  return (
    <div className="notes-toolbar">
      <div className="notes-toolbar__filters" role="group" aria-label="Filter notes">
        {FILTERS.map((f) => (
          <Chip key={f} Label={f} pressed={filter === f} onClick={() => { setFilter(f); onFilterChange?.(f); }} />
        ))}
      </div>
      <div className="notes-toolbar__search">
        <Field type="search" label="Search notes" placeholder="Search notes" onChange={(e) => onSearch?.(e.target.value)} />
      </div>
      {/* No icon-only chip in Tidepool: L + icon with no label, named by aria-label. */}
      <span className="notes-toolbar__pin">
        <Chip Size="L" Icon Label={null} aria-label="Pin note" pressed={pinned} onClick={() => { setPinned(!pinned); onPinChange?.(!pinned); }} />
      </span>
    </div>
  );
}

